using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Threading;
using System.Web.Script.Serialization;
namespace Nexus {
  public class PackageFile {public string Path;public string Hash;}
  public class InstallReceipt {public string repository;public string version;public string asset;public string digest;public string source;public bool localImport;public string downloadedAt;public List<PackageFile> files;}
  public static class UpdateManager {
    static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=32*1024*1024};}
    static string Display(string p){return p.StartsWith(@"\\?\UNC\")?@"\\"+p.Substring(8):p.StartsWith(@"\\?\")?p.Substring(4):p;}
    static string Hash(string file){using(var f=File.OpenRead(PortCatalog.FsPath(file)))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
    static string[] Files(string root){CheckLinks(root);return Directory.GetFiles(PortCatalog.FsPath(root),"*",SearchOption.AllDirectories).Select(Display).ToArray();}
    static void CheckLinks(string root){
      var pending=new Stack<string>();pending.Push(root);while(pending.Count>0){string path=pending.Pop();if((File.GetAttributes(PortCatalog.FsPath(path))&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("A instalação contém links ou pontos de montagem. Não foi alterada.");foreach(string file in Directory.GetFiles(PortCatalog.FsPath(path)))if((File.GetAttributes(file)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("A instalação contém links. Não foi alterada.");foreach(string dir in Directory.GetDirectories(PortCatalog.FsPath(path)))pending.Push(Display(dir));}
    }
    public static void WriteReceipt(PortEntry entry,PortRelease release,string root,CancellationToken token){
      var list=new List<PackageFile>();foreach(string f in Files(root)){token.ThrowIfCancellationRequested();string relative=PackageSupport.Relative(root,f);if(relative==".nexus-install.json")continue;list.Add(new PackageFile{Path=relative,Hash=Hash(f)});}
      var receipt=new InstallReceipt{repository=entry.Identity,version=release.Version,asset=release.AssetName,digest=release.Digest,source=entry.ProjectUrl,localImport=entry.ManualPackage,downloadedAt=DateTime.UtcNow.ToString("o"),files=list};File.WriteAllText(PortCatalog.FsPath(PortCatalog.ChildPath(root,".nexus-install.json")),Json().Serialize(receipt));
    }
    public static InstallReceipt Receipt(Game game){
      string root=game.InstallationKind=="Installer"?game.InstallerCacheRoot:game.ManagedInstallationRoot;if(String.IsNullOrEmpty(root)||!Directory.Exists(root))throw new InvalidDataException("Esta cópia não foi instalada pelo NEXUS.");
      string file=PortCatalog.ChildPath(root,".nexus-install.json");if(!File.Exists(file)||new FileInfo(file).Length>32*1024*1024)throw new InvalidDataException("Comprovante da instalação não encontrado.");var r=Json().Deserialize<InstallReceipt>(File.ReadAllText(file));if(r==null||r.repository!=game.Repository||r.version!=game.InstalledVersion)throw new InvalidDataException("O comprovante não corresponde a esta instalação.");return r;
    }
    public static bool Managed(Game game){try{Receipt(game);if(game.InstallationKind!="Installer"){PackageSupport.Relative(game.ManagedInstallationRoot,game.Executable);if(!String.IsNullOrEmpty(game.ConfigurationExecutable))PackageSupport.Relative(game.ManagedInstallationRoot,game.ConfigurationExecutable);}return File.Exists(game.Executable);}catch{return false;}}
    public static bool Available(Game game,PortRelease release){if(!String.Equals(game.InstalledVersion,release.Version,StringComparison.OrdinalIgnoreCase))return Newer(game.InstalledVersion,release.Version);if(String.IsNullOrEmpty(release.Digest))return false;var receipt=Receipt(game);return !String.IsNullOrEmpty(receipt.digest)&&!receipt.digest.Equals(release.Digest,StringComparison.OrdinalIgnoreCase);}
    public static void EnsureClosed(Game game){
      string root=String.IsNullOrEmpty(game.ManagedInstallationRoot)?null:Path.GetFullPath(game.ManagedInstallationRoot).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;
      foreach(var process in System.Diagnostics.Process.GetProcesses())using(process){string exe=null;try{exe=process.MainModule.FileName;}catch{}if(exe!=null&&(String.Equals(exe,game.Executable,StringComparison.OrdinalIgnoreCase)||root!=null&&exe.StartsWith(root,StringComparison.OrdinalIgnoreCase)))throw new IOException("Feche o jogo e o launcher deste port antes de atualizar.");}
    }
    public static bool Newer(string installed,string available){
      if(String.Equals(installed,available,StringComparison.OrdinalIgnoreCase))return false;
      var a=System.Text.RegularExpressions.Regex.Match(installed??"",@"^v?(\d+(?:\.\d+){1,3})(?:$|[-+])",System.Text.RegularExpressions.RegexOptions.IgnoreCase);var b=System.Text.RegularExpressions.Regex.Match(available??"",@"^v?(\d+(?:\.\d+){1,3})(?:$|[-+])",System.Text.RegularExpressions.RegexOptions.IgnoreCase);
      Version av,bv;if(a.Success&&b.Success&&Version.TryParse(a.Groups[1].Value,out av)&&Version.TryParse(b.Groups[1].Value,out bv)){av=new Version(av.Major,av.Minor,Math.Max(0,av.Build),Math.Max(0,av.Revision));bv=new Version(bv.Major,bv.Minor,Math.Max(0,bv.Build),Math.Max(0,bv.Revision));int result=bv.CompareTo(av);if(result!=0)return result>0;bool installedBeta=(installed??"").IndexOf('-')>=0,availableBeta=(available??"").IndexOf('-')>=0;if(!installedBeta&&availableBeta)return false;if(installedBeta&&!availableBeta)return true;if(!installedBeta&&!availableBeta)return false;var left=System.Text.RegularExpressions.Regex.Matches(installed.Substring(installed.IndexOf('-')+1).Split('+')[0],@"\d+|[^\d.]+").Cast<System.Text.RegularExpressions.Match>().Select(m=>m.Value).ToArray();var right=System.Text.RegularExpressions.Regex.Matches(available.Substring(available.IndexOf('-')+1).Split('+')[0],@"\d+|[^\d.]+").Cast<System.Text.RegularExpressions.Match>().Select(m=>m.Value).ToArray();for(int i=0;i<Math.Min(left.Length,right.Length);i++){long l,r;bool ln=Int64.TryParse(left[i],out l),rn=Int64.TryParse(right[i],out r);int compare=ln&&rn?r.CompareTo(l):ln!=rn?(ln?1:-1):StringComparer.OrdinalIgnoreCase.Compare(right[i],left[i]);if(compare!=0)return compare>0;}return right.Length>left.Length;}
      return true;
    }
    static bool DataFile(string relative){string extension=Path.GetExtension(relative).ToLowerInvariant();if(new[]{".ini",".cfg",".conf",".config",".json",".toml",".yaml",".yml",".xml",".sav",".srm",".key",".path"}.Contains(extension)||System.Text.RegularExpressions.Regex.IsMatch(Path.GetFileName(relative),"config|setting|option|control|binding|profile|game\\.path",System.Text.RegularExpressions.RegexOptions.IgnoreCase))return true;return relative.Split(Path.DirectorySeparatorChar).Any(x=>new[]{"save","saves","savegames","savedata","userdata","user","profiles","game","mods","assets","cache","shaders","shadercache","hdd","texturepacks"}.Contains(x,StringComparer.OrdinalIgnoreCase));}
    static void Copy(string from,string to){Directory.CreateDirectory(PortCatalog.FsPath(Path.GetDirectoryName(to)));File.Copy(PortCatalog.FsPath(from),PortCatalog.FsPath(to),true);}
    static string BundlePrefix(string executable,IEnumerable<string> files){int slash=executable.IndexOf(Path.DirectorySeparatorChar);if(slash<0)return "";string prefix=executable.Substring(0,slash+1);return files.Where(p=>p!=".nexus-install.json").All(p=>p.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))?prefix:"";}
    static string LegacyPrefix(string oldExecutable,string newExecutable,string newPrefix,IEnumerable<string> oldFiles){string tail=newExecutable.Substring(newPrefix.Length);if(oldExecutable.Equals(tail,StringComparison.OrdinalIgnoreCase))return "";int slash=oldExecutable.IndexOf(Path.DirectorySeparatorChar);if(slash>=0&&oldExecutable.Substring(slash+1).Equals(tail,StringComparison.OrdinalIgnoreCase))return oldExecutable.Substring(0,slash+1);return BundlePrefix(oldExecutable,oldFiles);}
    static string Map(string relative,string oldPrefix,string newPrefix){if(relative==".nexus-install.json")return relative;if(oldPrefix.Length>0&&relative.TrimEnd(Path.DirectorySeparatorChar).Equals(oldPrefix.TrimEnd(Path.DirectorySeparatorChar),StringComparison.OrdinalIgnoreCase))return newPrefix.TrimEnd(Path.DirectorySeparatorChar);return relative.StartsWith(oldPrefix,StringComparison.OrdinalIgnoreCase)?newPrefix+relative.Substring(oldPrefix.Length):relative;}
    static string MapSource(string path,string root,string oldPrefix,string newPrefix){if(String.IsNullOrEmpty(path))return path;string prefix=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;string full=Path.GetFullPath(path);if(full.Equals(prefix.TrimEnd(Path.DirectorySeparatorChar),StringComparison.OrdinalIgnoreCase)&&oldPrefix.Length==0)return newPrefix.Length==0?root:PortCatalog.ChildPath(root,newPrefix.TrimEnd(Path.DirectorySeparatorChar));if(!full.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))return path;string mapped=Map(full.Substring(prefix.Length),oldPrefix,newPrefix);return mapped.Length==0?root:PortCatalog.ChildPath(root,mapped);}
    public static Game Commit(PortEntry entry,string packageRoot,Game fresh,Game old,IProgress<InstallProgress> progress,CancellationToken token){
      if(old==null||old.Repository!=entry.Identity||old.InstallationKind=="Installer")throw new InvalidDataException("Instalação incompatível com atualização portátil.");var oldReceipt=Receipt(old);string target=Path.GetFullPath(old.ManagedInstallationRoot).TrimEnd(Path.DirectorySeparatorChar),parent=Path.GetDirectoryName(target);if(String.IsNullOrEmpty(parent)||target==Path.GetPathRoot(target))throw new InvalidDataException("Pasta gerenciada inválida.");
      PackageSupport.Relative(target,old.Executable);EnsureClosed(old);CheckLinks(target);CheckLinks(packageRoot);
      string merged=PortCatalog.ChildPath(parent,".nexus-update-"+Guid.NewGuid().ToString("N")),backup=PortCatalog.ChildPath(parent,Path.GetFileName(target)+".nexus-backup-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(PortCatalog.FsPath(merged));
      try{
        var oldFiles=Files(target);var nextFiles=Files(packageRoot);string oldExe=PackageSupport.Relative(target,old.Executable),newExe=PackageSupport.Relative(packageRoot,fresh.Executable),newPrefix=BundlePrefix(newExe,nextFiles.Select(f=>PackageSupport.Relative(packageRoot,f))),oldPrefix=oldReceipt.files!=null&&oldReceipt.files.Count>0?BundlePrefix(oldExe,oldReceipt.files.Select(f=>f.Path)):LegacyPrefix(oldExe,newExe,newPrefix,oldFiles.Select(f=>PackageSupport.Relative(target,f)));
        long required=oldFiles.Sum(f=>new FileInfo(PortCatalog.FsPath(f)).Length);var drive=new DriveInfo(Path.GetPathRoot(target));if(drive.AvailableFreeSpace<required+128L*1024*1024)throw new IOException("Espaço insuficiente para preservar a instalação e criar a atualização.");
        var mapped=new HashSet<string>(StringComparer.OrdinalIgnoreCase);int count=0;foreach(string file in oldFiles){token.ThrowIfCancellationRequested();string relative=Map(PackageSupport.Relative(target,file),oldPrefix,newPrefix);if(!mapped.Add(relative))throw new IOException("Os caminhos de dados desta atualização entram em conflito. A instalação anterior foi preservada.");Copy(file,PortCatalog.ChildPath(merged,relative));if(++count%50==0&&progress!=null)progress.Report(new InstallProgress{Message="Preservando arquivos, saves e configurações…",Percent=80+count*8.0/Math.Max(1,oldFiles.Length)});}
        var nextPaths=new HashSet<string>(nextFiles.Select(f=>PackageSupport.Relative(packageRoot,f)),StringComparer.OrdinalIgnoreCase);var previousHashes=(oldReceipt.files??new List<PackageFile>()).ToDictionary(f=>Map(f.Path,oldPrefix,newPrefix),f=>f.Hash,StringComparer.OrdinalIgnoreCase);
        foreach(var f in oldReceipt.files??new List<PackageFile>()){string relative=Map(f.Path,oldPrefix,newPrefix);if(!nextPaths.Contains(relative)&&!DataFile(relative)){token.ThrowIfCancellationRequested();string obsolete=PortCatalog.ChildPath(merged,relative);if(File.Exists(PortCatalog.FsPath(obsolete))&&Hash(obsolete)==f.Hash)File.Delete(PortCatalog.FsPath(obsolete));}}
        foreach(string file in nextFiles){token.ThrowIfCancellationRequested();string relative=PackageSupport.Relative(packageRoot,file),to=PortCatalog.ChildPath(merged,relative);if(relative!=".nexus-install.json"&&File.Exists(PortCatalog.FsPath(to))&&DataFile(relative)){string hash;if(!previousHashes.TryGetValue(relative,out hash)||Hash(to)!=hash)continue;}Copy(file,to);}
        string play=PackageSupport.Relative(packageRoot,fresh.Executable),config=String.IsNullOrEmpty(fresh.ConfigurationExecutable)?null:PackageSupport.Relative(packageRoot,fresh.ConfigurationExecutable),source=MapSource(old.SourceGameDirectory,target,oldPrefix,newPrefix),contentSource=MapSource(old.GameContentSource,target,oldPrefix,newPrefix);token.ThrowIfCancellationRequested();
        EnsureClosed(old);Directory.Move(PortCatalog.FsPath(target),PortCatalog.FsPath(backup));try{Directory.Move(PortCatalog.FsPath(merged),PortCatalog.FsPath(target));}catch{Directory.Move(PortCatalog.FsPath(backup),PortCatalog.FsPath(target));throw;}
        fresh.Executable=PortCatalog.ChildPath(target,play);fresh.ConfigurationExecutable=config==null?null:PortCatalog.ChildPath(target,config);fresh.WorkingDirectory=Path.GetDirectoryName(fresh.Executable);fresh.ManagedInstallationRoot=target;fresh.UpdateBackupDirectory=backup;PackageSupport.PreserveMetadata(fresh,old);fresh.SourceGameDirectory=source;fresh.GameContentSource=contentSource;return fresh;
      }finally{if(Directory.Exists(PortCatalog.FsPath(merged))&&Path.GetFileName(merged).StartsWith(".nexus-update-",StringComparison.Ordinal))Directory.Delete(PortCatalog.FsPath(merged),true);}
    }
    public static void Rollback(Game next,Game old){
      if(String.IsNullOrEmpty(next.UpdateBackupDirectory)||!Directory.Exists(next.UpdateBackupDirectory))return;string root=Path.GetFullPath(old.ManagedInstallationRoot),parent=Path.GetDirectoryName(root),backup=Path.GetFullPath(next.UpdateBackupDirectory);if(!backup.StartsWith(root+".nexus-backup-",StringComparison.OrdinalIgnoreCase)||Path.GetDirectoryName(backup)!=parent)throw new InvalidDataException("Backup de atualização inválido.");string failed=PortCatalog.ChildPath(parent,".nexus-failed-"+Guid.NewGuid().ToString("N"));Directory.Move(PortCatalog.FsPath(root),PortCatalog.FsPath(failed));try{Directory.Move(PortCatalog.FsPath(backup),PortCatalog.FsPath(root));}catch{Directory.Move(PortCatalog.FsPath(failed),PortCatalog.FsPath(root));throw;}
    }
  }
}
